import 'dart:convert';
import 'package:flutter/widgets.dart';

/// PNG image embedded directly in Dart, so no separate asset declaration is needed.
class RegisterLoginImage extends StatelessWidget {
  const RegisterLoginImage({super.key});

  static const String _base64Image = '';

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_base64Image),
      fit: BoxFit.contain,
      width: double.infinity,
    );
  }
}